    "protect-pdf": { name: "\u09AA\u09BF\u09A1\u09BF\u098F\u09AB \u09AA\u09BE\u09B8\u0993\u09AF\u09BC\u09BE\u09B0\u09CD\u09A1 \u09B8\u09C1\u09B0\u0995\u09CD\u09B7\u09BE", desc: "\u09E8\u09EB\u09EC-\u09AC\u09BF\u099F \u098F\u0987\u098F\u09B8 \u098F\u09A8\u0995\u09CD\u09B0\u09BF\u09AA\u09B6\u09A8 \u09A6\u09BF\u09AF\u09BC\u09C7 \u0997\u09CB\u09AA\u09A8\u09C0\u09AF\u09BC \u09A8\u09A5\u09BF \u09B8\u09C1\u09B0\u0995\u09CD\u09B7\u09BF\u09A4 \u0995\u09B0\u09C1\u09A8\u0964" },
    "unlock-pdf": { name: "\u09AA\u09BF\u09A1\u09BF\u098F\u09AB \u0986\u09A8\u09B2\u0995 \u0995\u09B0\u09C1\u09A8", desc: "\u09B8\u09C1\u09B0\u0995\u09CD\u09B7\u09BF\u09A4 \u09AA\u09BF\u09A1\u09BF\u098F\u09AB \u09A5\u09C7\u0995\u09C7 \u09AA\u09BE\u09B8\u0993\u09AF\u09BC\u09BE\u09B0\u09CD\u09A1 \u0993 \u09AC\u09BF\u09A7\u09BF\u09A8\u09BF\u09B7\u09C7\u09A7 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09BE\u09B9\u09BE\u09B0 \u0995\u09B0\u09C1\u09A8\u0964" },
    "ocr-pdf": { name: "\u0993\u09B8\u09BF\u0986\u09B0 \u099F\u09C7\u0995\u09CD\u09B8\u099F \u09B0\u09BF\u0995\u0997\u09A8\u09BF\u09B6\u09A8", desc: "\u09B8\u09CD\u0995\u09CD\u09AF\u09BE\u09A8 \u0995\u09B0\u09BE \u09A1\u0995\u09C1\u09AE\u09C7\u09A8\u09CD\u099F \u09A5\u09C7\u0995\u09C7 \u098F\u09A1\u09BF\u099F\u09C7\u09AC\u09B2 \u099F\u09C7\u0995\u09CD\u09B8\u099F \u09AC\u09C7\u09B0 \u0995\u09B0\u09C1\u09A8\u0964" },
