app2.post(["/api/translate", "/api/ai/translate"], async (req, res) => {
  res.setHeader("Content-Type", "application/json");
  try {
    const { documentText, sourceText, text, targetLanguage = "Hindi" } = req.body || {};
    const rawInput = (sourceText || documentText || text || "").replace(/\0/g, "").replace(/\r\n/g, "\n").trim();
    if (!rawInput) {
      return res.status(400).json({
        success: false,
        error: "No source text provided for translation. Please provide extracted document text."
      });
    }
    if (!process.env.GEMINI_API_KEY) {
      return res.status(503).json({
        success: false,
        error: "GEMINI_API_KEY is not configured on the server. Please add your Gemini API key in Settings > Secrets."
      });
    }
    const ai = getGeminiClient();
    const cleanTargetLang = (targetLanguage || "Hindi").toString().trim();
    const chunks = splitTextIntoChunks(rawInput, 25e3);
    const translatedChunks = [];
    let modelUsed = "gemini-2.5-flash";
    for (let i = 0; i < chunks.length; i++) {
      const translatedChunk = await translateChunkWithGemini(ai, chunks[i], cleanTargetLang);
      translatedChunks.push(translatedChunk.text);
      modelUsed = translatedChunk.modelUsed;
    }
    const fullTranslation = translatedChunks.join("\n\n");
    return res.status(200).json({
      success: true,
      result: fullTranslation,
      translatedText: fullTranslation,
      targetLanguage: cleanTargetLang,
      chunksProcessed: chunks.length,
      totalLength: fullTranslation.length,
      modelUsed
    });
  } catch (error) {
    if (req.quotaContext) {
      rollbackAiQuota(req.quotaContext).catch(() => {
      });
    }
    console.error("[Translation Route Error]:", error?.message || "Translation failure");
    const rawMsg = error?.message || "Failed to process translation request with Gemini AI.";
    const isRateLimit = rawMsg.includes("429") || rawMsg.toLowerCase().includes("quota") || rawMsg.toLowerCase().includes("resource exhausted");
    const isHighDemand = rawMsg.includes("503") || rawMsg.toLowerCase().includes("high demand") || rawMsg.toLowerCase().includes("unavailable");
    const isApiKeyError = rawMsg.toLowerCase().includes("api_key") || rawMsg.toLowerCase().includes("api key") || rawMsg.includes("403") || rawMsg.includes("401");
    const statusCode = isRateLimit || isHighDemand ? 429 : isApiKeyError ? 401 : 500;
    const retryMatch = rawMsg.match(/retry in ([0-9.]+)s/i) || JSON.stringify(error?.details || {}).match(/"retryDelay":"(\d+)s"/i);
    const waitSeconds = retryMatch ? Math.ceil(parseFloat(retryMatch[1])) : 20;
    const userFriendlyError = isRateLimit ? `Gemini AI rate limit reached. Please wait ${waitSeconds} seconds before retrying.` : isHighDemand ? `Gemini AI is experiencing temporary high demand. Please retry in ${waitSeconds} seconds.` : isApiKeyError ? "Translation service authentication is currently unavailable." : "Failed to process document translation request. Please try again.";
    return res.status(statusCode).json({
      success: false,
      error: userFriendlyError,
      message: userFriendlyError,
      retryAfterSeconds: waitSeconds,
      statusCode
    });
  }
});
